import React, { useEffect, useRef, useState } from "react";

// Captures d'écran réelles du projet K-Hopes Immo (dashboard, détail chantier, page d'accueil).
// Pour les autres projets : ajoute simplement les data-URIs (ou import d'image) dans un
// tableau `images: [...]` sur le projet concerné dans PROJECTS ci-dessous — la galerie
// cliquable s'active automatiquement dès qu'un projet a au moins une image.
const KHOPES_IMG_1 = "data:image/jpeg;base64,";
const KHOPES_IMG_2 = "data:image/jpeg;base64,";
const KHOPES_IMG_3 = "data:image/jpeg;base64,";
const WELLEAT_LOGO = "data:image/png;base64,";

const CSS = `
  @import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500;600;700&family=Manrope:wght@400;500;600;700;800&display=swap');
  .bk-root{
    --bg:#F7F8FB; --surface:#FFFFFF; --surface-2:#EEF1F7;
    --line:rgba(16,24,40,.09); --line-strong:rgba(16,24,40,.18);
    --text:#12151F; --muted:#636B7A;
    --yolo:#E8A400; --yolo-soft:#FFF3D6;
    --teal:#0EA894; --teal-soft:#DEF7F3;
    --mono:'JetBrains Mono', monospace; --sans:'Manrope', sans-serif;
    background:var(--bg); color:var(--text); font-family:var(--sans);
    line-height:1.6; position:relative; overflow-x:hidden;
  }
  .bk-root *{box-sizing:border-box;}
  .bk-root a{color:inherit;text-decoration:none;}
  .bk-root ::selection{background:var(--yolo);color:#12151F;}
  .bk-wrap{max-width:1120px;margin:0 auto;padding:0 32px;}

  .bk-grid-bg{
    position:absolute;inset:0;z-index:0;
    background-image:linear-gradient(var(--line) 1px, transparent 1px),linear-gradient(90deg, var(--line) 1px, transparent 1px);
    background-size:48px 48px;
    mask-image:radial-gradient(ellipse 80% 60% at 50% 0%, black 20%, transparent 75%);
    opacity:.7;
  }
  .bk-blob{position:absolute;z-index:0;border-radius:50%;filter:blur(70px);opacity:.35;animation:bk-drift 18s ease-in-out infinite;will-change:transform;}
  .bk-blob1{width:480px;height:480px;background:var(--yolo);top:-160px;left:-140px;}
  .bk-blob2{width:420px;height:420px;background:var(--teal);top:200px;right:-160px;animation-delay:-6s;}
  .bk-blob3{width:360px;height:360px;background:var(--yolo);bottom:-140px;left:30%;animation-delay:-11s;opacity:.22;}
  @keyframes bk-drift{0%,100%{transform:translate(0,0) scale(1);}33%{transform:translate(30px,-40px) scale(1.08);}66%{transform:translate(-25px,25px) scale(.95);}}

  .bk-particle{position:absolute;border-radius:50%;background:var(--yolo);opacity:.5;pointer-events:none;animation:bk-floaty linear infinite;}
  .bk-particle.teal{background:var(--teal);}
  @keyframes bk-floaty{0%{transform:translateY(0) translateX(0);opacity:0;}10%{opacity:.6;}90%{opacity:.6;}100%{transform:translateY(-140px) translateX(20px);opacity:0;}}

  .bk-header{position:sticky;top:0;left:0;right:0;z-index:100;background:rgba(247,248,251,.7);backdrop-filter:blur(10px);border-bottom:1px solid var(--line);}
  .bk-nav{display:flex;align-items:center;justify-content:space-between;padding:18px 32px;max-width:1120px;margin:0 auto;}
  .bk-logo{font-family:var(--mono);font-weight:600;font-size:15px;letter-spacing:.02em;display:flex;align-items:center;gap:8px;}
  .bk-logo .dot{width:8px;height:8px;background:var(--yolo);border-radius:50%;animation:bk-blink 1.6s ease-in-out infinite;}
  @keyframes bk-blink{0%,100%{opacity:1;box-shadow:0 0 0 0 rgba(232,164,0,.5);}50%{opacity:.4;box-shadow:0 0 0 6px rgba(232,164,0,0);}}
  .bk-navlinks{display:flex;gap:32px;font-size:14px;color:var(--muted);}
  .bk-navlinks a{transition:color .2s;position:relative;}
  .bk-navlinks a:hover, .bk-navlinks a.active{color:var(--text);}
  .bk-navlinks a::after{content:'';position:absolute;left:0;bottom:-6px;width:0;height:2px;background:var(--yolo);transition:width .25s;}
  .bk-navlinks a:hover::after, .bk-navlinks a.active::after{width:100%;}
  .bk-burger{display:none;flex-direction:column;gap:5px;cursor:pointer;background:none;border:none;}
  .bk-burger span{width:22px;height:2px;background:var(--text);display:block;}
  .bk-mobile-menu{position:fixed;top:60px;left:0;right:0;background:var(--surface);border-bottom:1px solid var(--line);z-index:99;padding:20px 32px;flex-direction:column;gap:18px;font-size:15px;}

  .bk-hero{min-height:100vh;display:flex;align-items:center;position:relative;padding:60px 0 60px;overflow:hidden;}
  .bk-spotlight{position:absolute;inset:0;pointer-events:none;z-index:0;background:radial-gradient(360px circle at var(--mx,50%) var(--my,30%), rgba(232,164,0,.12), transparent 60%);transition:background .1s;}
  .bk-hero .bk-wrap{position:relative;z-index:1;}
  .bk-fade-up{opacity:0;transform:translateY(22px);animation:bk-fadeUp .8s cubic-bezier(.16,1,.3,1) forwards;}
  @keyframes bk-fadeUp{to{opacity:1;transform:translateY(0);}}
  .bk-tag{display:inline-flex;align-items:center;gap:8px;font-family:var(--mono);font-size:12px;color:#7A5A00;border:1px solid rgba(232,164,0,.35);background:var(--yolo-soft);padding:6px 12px;border-radius:3px;margin-bottom:28px;}
  .bk-tag::before{content:'';width:6px;height:6px;background:var(--yolo);border-radius:50%;animation:bk-blink 1.6s ease-in-out infinite;}
  .bk-headline{font-size:clamp(30px,6vw,72px);font-weight:800;letter-spacing:-.02em;line-height:1.05;max-width:820px;min-height:2.25em;}
  .bk-cycle{color:var(--yolo);display:inline-block;min-width:1ch;border-right:3px solid var(--yolo);padding-right:4px;}
  .bk-hero-sub{max-width:600px;color:var(--muted);font-size:17px;margin-top:24px;}
  .bk-hero-meta{display:flex;gap:28px;flex-wrap:wrap;margin-top:20px;font-family:var(--mono);font-size:13px;color:var(--muted);}
  .bk-hero-meta span{display:flex;align-items:center;gap:8px;}
  .bk-cta-row{display:flex;gap:16px;margin-top:40px;flex-wrap:wrap;}
  .bk-btn{font-family:var(--mono);font-size:13px;padding:13px 24px;border-radius:3px;display:inline-flex;align-items:center;gap:10px;transition:all .2s;border:1px solid transparent;cursor:pointer;}
  .bk-btn-primary{background:var(--yolo);color:#12151F;font-weight:600;}
  .bk-btn-primary:hover{background:#ffb814;transform:translateY(-2px);box-shadow:0 10px 24px rgba(232,164,0,.35);}
  .bk-btn-ghost{border-color:var(--line-strong);color:var(--text);background:var(--surface);}
  .bk-btn-ghost:hover{border-color:var(--teal);color:var(--teal);transform:translateY(-2px);}

  .bk-terminal-card{
    background:#12151F;border-radius:12px;overflow:hidden;
    box-shadow:0 30px 60px rgba(16,24,40,.22), 0 0 0 1px rgba(255,255,255,.04);
    animation:bk-terminal-float 5s ease-in-out infinite;
  }
  @keyframes bk-terminal-float{0%,100%{transform:translateY(0);}50%{transform:translateY(-10px);}}
  .bk-terminal-bar{
    display:flex;align-items:center;gap:8px;padding:11px 14px;background:#1B2030;
    border-bottom:1px solid rgba(255,255,255,.06);
  }
  .bk-terminal-dot{width:10px;height:10px;border-radius:50%;}
  .bk-terminal-bar .bk-terminal-filename{
    margin-left:8px;font-family:var(--mono);font-size:11.5px;color:#8B93A7;
  }
  .bk-terminal-body{
    padding:20px 22px;font-family:var(--mono);font-size:13px;line-height:1.85;
    min-height:230px;white-space:pre-wrap;word-break:break-word;
  }
  .bk-tk-kw{color:#F5789A;}
  .bk-tk-fn{color:#5FD3C4;}
  .bk-tk-str{color:#E8A400;}
  .bk-tk-cm{color:#5A6272;}
  .bk-tk-var{color:#C8CFE0;}
  .bk-tk-out{color:#3AC7B0;}
  .bk-terminal-cursor{
    display:inline-block;width:7px;height:15px;background:var(--yolo);vertical-align:-2px;
    animation:bk-cursor-blink .9s step-end infinite;
  }
  @keyframes bk-cursor-blink{0%,100%{opacity:1;}50%{opacity:0;}}

  .bk-float-badge{
    position:absolute;font-family:var(--mono);font-size:11px;font-weight:700;color:#12151F;
    padding:5px 11px;border-radius:5px;box-shadow:0 10px 22px rgba(16,24,40,.18);
    animation:bk-badge-float 4.5s ease-in-out infinite;
  }
  @keyframes bk-badge-float{0%,100%{transform:translateY(0) rotate(-2deg);}50%{transform:translateY(-8px) rotate(1deg);}}

  .bk-stats-strip{display:flex;gap:0;margin-top:56px;border-top:1px solid var(--line);padding-top:28px;flex-wrap:wrap;}
  .bk-stat{flex:1;min-width:140px;}
  .bk-stat-num{font-family:var(--mono);font-size:32px;font-weight:700;color:var(--yolo);}
  .bk-stat-label{font-size:12.5px;color:var(--muted);margin-top:4px;}

  .bk-marquee-wrap{position:relative;z-index:1;border-top:1px solid var(--line);border-bottom:1px solid var(--line);background:var(--surface);overflow:hidden;padding:18px 0;}
  .bk-marquee-track{display:flex;gap:40px;white-space:nowrap;width:max-content;animation:bk-scrollLeft 26s linear infinite;font-family:var(--mono);font-size:13px;color:var(--muted);}
  .bk-marquee-track span{display:flex;align-items:center;gap:10px;}
  .bk-marquee-track span::before{content:'◆';color:var(--yolo);font-size:9px;}
  @keyframes bk-scrollLeft{from{transform:translateX(0);}to{transform:translateX(-50%);}}

  .bk-section{padding:110px 0;border-top:1px solid var(--line);position:relative;z-index:1;}
  .bk-eyebrow{font-family:var(--mono);font-size:12px;color:var(--teal);letter-spacing:.08em;text-transform:uppercase;margin-bottom:14px;display:block;}
  .bk-title{font-size:clamp(28px,4vw,42px);font-weight:800;letter-spacing:-.01em;margin-bottom:6px;position:relative;display:inline-block;}
  .bk-title-underline{display:block;height:3px;width:0;background:var(--yolo);border-radius:2px;margin-bottom:26px;transition:width .8s cubic-bezier(.16,1,.3,1) .15s;}
  .bk-reveal.in .bk-title-underline{width:64px;}
  .bk-section-lead{color:var(--muted);max-width:640px;font-size:16px;margin-bottom:56px;}

  .bk-reveal{opacity:0;transform:translateY(28px);transition:opacity .7s cubic-bezier(.16,1,.3,1), transform .7s cubic-bezier(.16,1,.3,1);}
  .bk-reveal.in{opacity:1;transform:translateY(0);}
  .bk-stagger.in > *{opacity:0;transform:translateY(16px);animation:bk-fadeUp .6s cubic-bezier(.16,1,.3,1) forwards;}

  .bk-profil-text{max-width:760px;font-size:17px;color:#333A47;}
  .bk-profil-text p + p{margin-top:16px;}

  .bk-why-grid{display:grid;grid-template-columns:300px 1fr;gap:64px;align-items:center;}
  .bk-think-svg{width:100%;max-width:320px;display:block;margin:0 auto;}
  .bk-think-orbit{animation:bk-orbit-spin 40s linear infinite;transform-origin:180px 180px;}
  @keyframes bk-orbit-spin{from{transform:rotate(0deg);}to{transform:rotate(360deg);}}
  .bk-think-float{animation:bk-think-bob 3.6s ease-in-out infinite;transform-origin:center;}
  @keyframes bk-think-bob{0%,100%{transform:translateY(0);}50%{transform:translateY(-10px);}}
  .bk-robot-gear{animation:bk-gear-spin 6s linear infinite;transform-origin:266px 96px;}
  @keyframes bk-gear-spin{from{transform:rotate(0deg);}to{transform:rotate(360deg);}}
  .bk-robot-eye{animation:bk-eye-blink 3.2s ease-in-out infinite;transform-origin:center;}
  .bk-robot-eye.right{animation-delay:.15s;}
  @keyframes bk-eye-blink{0%,92%,100%{transform:scaleY(1);}96%{transform:scaleY(.15);}}
  .bk-robot-dots circle{animation:bk-pulseDot 1.4s ease-in-out infinite;}

  .bk-why-cycle{min-height:170px;display:flex;flex-direction:column;justify-content:center;}
  .bk-why-cycle-item{animation:bk-why-in .55s cubic-bezier(.16,1,.3,1) both;}
  @keyframes bk-why-in{
    0%{opacity:0;transform:translateX(24px);}
    100%{opacity:1;transform:translateX(0);}
  }
  .bk-why-cycle-icon{
    font-size:34px;display:inline-flex;align-items:center;justify-content:center;
    width:56px;height:56px;border-radius:50%;background:var(--yolo-soft);margin-bottom:18px;
  }
  .bk-why-cycle-item h4{font-size:22px;font-weight:800;margin-bottom:10px;letter-spacing:-.01em;}
  .bk-why-cycle-item p{color:var(--muted);font-size:15.5px;line-height:1.6;max-width:480px;}
  .bk-why-dots{display:flex;gap:8px;margin-top:26px;}
  .bk-why-dots span{
    width:9px;height:9px;border-radius:5px;background:var(--line-strong);cursor:pointer;
    transition:width .3s, background .3s;display:block;
  }
  .bk-why-dots span.active{width:30px;background:var(--yolo);}
  @media (max-width:860px){
    .bk-why-grid{grid-template-columns:1fr;gap:32px;}
    .bk-why-cycle{text-align:center;align-items:center;}
    .bk-why-cycle-item p{max-width:none;}
    .bk-why-dots{justify-content:center;}
  }


  .bk-skill-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:1px;background:var(--line);border:1px solid var(--line);border-radius:8px;overflow:hidden;}
  .bk-skill-col{background:var(--surface);padding:28px 24px;}
  .bk-skill-col h3{font-family:var(--mono);font-size:12px;color:var(--yolo);text-transform:uppercase;letter-spacing:.06em;margin-bottom:16px;display:flex;align-items:center;gap:8px;}
  .bk-chip-list{display:flex;flex-wrap:wrap;gap:8px;}
  .bk-chip{font-size:13px;padding:6px 12px;border:1px solid var(--line-strong);border-radius:20px;color:#242A35;background:var(--surface-2);}

  .bk-exp-card{border:1px solid var(--line);background:var(--surface);border-radius:8px;padding:32px;margin-bottom:20px;transition:box-shadow .25s, transform .25s;}
  .bk-exp-card:hover{box-shadow:0 16px 32px rgba(16,24,40,.08);transform:translateY(-3px);}
  .bk-exp-head{display:flex;justify-content:space-between;align-items:baseline;flex-wrap:wrap;gap:8px 20px;margin-bottom:6px;}
  .bk-exp-head-main{display:flex;align-items:center;gap:12px;flex-wrap:wrap;}
  .bk-exp-logo{width:34px;height:34px;object-fit:contain;border-radius:6px;background:var(--surface-2);padding:4px;flex-shrink:0;}
  .bk-exp-role{font-size:19px;font-weight:700;}
  .bk-exp-company{color:var(--yolo);font-family:var(--mono);font-size:14px;}
  .bk-exp-date{font-family:var(--mono);font-size:12px;color:var(--muted);white-space:nowrap;}
  .bk-exp-loc{color:var(--muted);font-size:13px;margin-bottom:16px;}
  .bk-exp-list{list-style:none;padding:0;margin:0;}
  .bk-exp-list li{position:relative;padding-left:20px;color:#333A47;font-size:14.5px;margin-bottom:8px;}
  .bk-exp-list li::before{content:'▸';position:absolute;left:0;color:var(--teal);}

  .bk-proj-note{font-size:13px;color:var(--muted);margin:-38px 0 40px;font-style:italic;}
  .bk-proj-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:24px;}
  .bk-proj-card{position:relative;border:1px solid var(--line);background:var(--surface);border-radius:8px;overflow:hidden;transition:border-color .25s, transform .1s, box-shadow .25s;}
  .bk-proj-card:hover{border-color:var(--yolo);box-shadow:0 20px 40px rgba(16,24,40,.10);}
  .bk-proj-card::before, .bk-proj-card::after{content:'';position:absolute;width:14px;height:14px;border:2px solid var(--yolo);opacity:0;transition:opacity .25s;z-index:2;}
  .bk-proj-card::before{top:-1px;left:-1px;border-right:none;border-bottom:none;}
  .bk-proj-card::after{bottom:-1px;right:-1px;border-left:none;border-top:none;}
  .bk-proj-card:hover::before,.bk-proj-card:hover::after{opacity:1;}
  .bk-card-media{position:relative;height:150px;background:var(--surface-2);border-bottom:1px solid var(--line);overflow:hidden;}
  .bk-card-media.has-images{cursor:pointer;}
  .bk-card-media img{width:100%;height:calc(100% - 26px);object-fit:cover;display:block;position:absolute;bottom:0;left:0;transition:transform .4s ease, filter .3s ease;}
  .bk-proj-card:hover .bk-card-media img{transform:scale(1.05);}
  .bk-gallery-overlay{
    position:absolute;left:0;right:0;bottom:0;height:calc(100% - 26px);
    display:flex;align-items:center;justify-content:center;gap:8px;
    background:rgba(18,21,31,0);color:#fff;font-family:var(--mono);font-size:12px;
    opacity:0;transition:opacity .25s, background .25s;
  }
  .bk-proj-card:hover .bk-gallery-overlay{opacity:1;background:rgba(18,21,31,.45);}
  .bk-gallery-badge{
    position:absolute;right:8px;bottom:8px;background:rgba(18,21,31,.72);color:#fff;
    font-family:var(--mono);font-size:10.5px;padding:3px 8px;border-radius:12px;
    display:flex;align-items:center;gap:5px;z-index:2;
  }

  .bk-matrix-canvas{
    position:absolute;inset:0;z-index:0;pointer-events:none;
    mask-image:radial-gradient(ellipse 70% 60% at 50% 15%, black 15%, transparent 72%);
    opacity:.4;
  }
  .bk-shimmer{
    background:linear-gradient(90deg, var(--yolo), var(--teal), var(--yolo));
    background-size:200% auto;
    -webkit-background-clip:text;background-clip:text;color:transparent;
    animation:bk-shimmer-move 3.5s linear infinite;
  }
  @keyframes bk-shimmer-move{0%{background-position:0% center;}100%{background-position:200% center;}}

  .bk-confetti-piece{
    position:fixed;z-index:500;top:0;left:0;pointer-events:none;border-radius:2px;
    animation:bk-confetti-fall 1.4s cubic-bezier(.25,.46,.45,.94) forwards;
  }
  @keyframes bk-confetti-fall{
    0%{transform:translate(var(--cx), var(--cy)) rotate(0deg) scale(1);opacity:1;}
    100%{transform:translate(calc(var(--cx) + var(--dx)), calc(var(--cy) + var(--dy))) rotate(var(--rot)) scale(.4);opacity:0;}
  }
  .bk-lightbox-backdrop{
    position:fixed;inset:0;z-index:1000;background:rgba(12,14,20,.88);
    display:flex;align-items:center;justify-content:center;padding:32px;
    animation:bk-fadeUp .25s ease forwards;
  }
  .bk-lightbox-inner{position:relative;max-width:1000px;width:100%;}
  .bk-lightbox-inner img{width:100%;max-height:78vh;object-fit:contain;border-radius:8px;display:block;background:#0B0F1A;}
  .bk-lightbox-close{
    position:absolute;top:-44px;right:0;background:none;border:1px solid rgba(255,255,255,.3);color:#fff;
    width:36px;height:36px;border-radius:50%;font-size:16px;cursor:pointer;transition:background .2s;
  }
  .bk-lightbox-close:hover{background:rgba(255,255,255,.15);}
  .bk-lightbox-nav{
    position:absolute;top:50%;transform:translateY(-50%);background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.25);
    color:#fff;width:42px;height:42px;border-radius:50%;cursor:pointer;font-size:18px;transition:background .2s;
  }
  .bk-lightbox-nav:hover{background:rgba(255,255,255,.25);}
  .bk-lightbox-nav.prev{left:-54px;}
  .bk-lightbox-nav.next{right:-54px;}
  .bk-lightbox-caption{color:#C7CDDB;font-family:var(--mono);font-size:12.5px;text-align:center;margin-top:14px;}
  .bk-lightbox-dots{display:flex;justify-content:center;gap:6px;margin-top:14px;}
  .bk-lightbox-dots span{width:6px;height:6px;border-radius:50%;background:rgba(255,255,255,.3);cursor:pointer;transition:background .2s;}
  .bk-lightbox-dots span.active{background:var(--yolo);}
  @media (max-width:640px){
    .bk-lightbox-nav.prev{left:4px;}
    .bk-lightbox-nav.next{right:4px;}
  }
  .bk-browser-bar{display:flex;align-items:center;gap:6px;padding:8px 10px;background:var(--surface);border-bottom:1px solid var(--line);}
  .bk-browser-bar i{width:8px;height:8px;border-radius:50%;background:var(--line-strong);display:block;font-style:normal;}
  .bk-browser-bar .bk-url{font-family:var(--mono);font-size:9.5px;color:var(--muted);background:var(--surface-2);padding:2px 8px;border-radius:8px;margin-left:6px;flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
  .bk-media-svg{width:100%;height:calc(100% - 26px);display:block;transition:transform .4s ease;}
  .bk-proj-card:hover .bk-media-svg{transform:scale(1.03);}
  .bk-proj-body{padding:26px 30px 30px;}
  .bk-proj-label{font-family:var(--mono);font-size:10px;color:var(--yolo);text-transform:uppercase;letter-spacing:.06em;margin-bottom:10px;display:block;}
  .bk-proj-card h3{font-size:19px;font-weight:700;margin-bottom:12px;line-height:1.3;}
  .bk-proj-card p{color:var(--muted);font-size:14px;margin-bottom:18px;}
  .bk-tech-tags{display:flex;flex-wrap:wrap;gap:6px;}
  .bk-tech-tags span{font-family:var(--mono);font-size:11px;color:#0B7C6C;border:1px solid rgba(14,168,148,.3);background:var(--teal-soft);padding:3px 8px;border-radius:3px;}

  .bk-scan-line{animation:bk-scanY 2.6s ease-in-out infinite;}
  @keyframes bk-scanY{0%,100%{transform:translateY(0);}50%{transform:translateY(74px);}}
  .bk-grow-bar{transform-origin:bottom;animation:bk-growBar 2.4s ease-in-out infinite alternate;}
  @keyframes bk-growBar{from{transform:scaleY(.5);}to{transform:scaleY(1);}}
  .bk-pulse-dot{animation:bk-pulseDot 1.8s ease-in-out infinite;}
  @keyframes bk-pulseDot{0%,100%{opacity:.3;}50%{opacity:1;}}
  .bk-draw-line{stroke-dasharray:240;stroke-dashoffset:240;animation:bk-drawLine 3s ease-in-out infinite;}
  @keyframes bk-drawLine{0%{stroke-dashoffset:240;}50%{stroke-dashoffset:0;}100%{stroke-dashoffset:-240;}}

  .bk-timeline{position:relative;max-width:760px;}
  .bk-timeline::before{content:'';position:absolute;left:7px;top:8px;bottom:8px;width:1px;background:var(--line-strong);}
  .bk-t-item{position:relative;padding-left:40px;margin-bottom:40px;}
  .bk-t-item:last-child{margin-bottom:0;}
  .bk-t-dot{position:absolute;left:0;top:4px;width:16px;height:16px;border-radius:50%;background:var(--surface);border:2px solid var(--yolo);}
  .bk-t-item.in .bk-t-dot{animation:bk-ping-dot .9s ease-out;}
  @keyframes bk-ping-dot{0%{box-shadow:0 0 0 0 rgba(232,164,0,.5);}100%{box-shadow:0 0 0 12px rgba(232,164,0,0);}}
  .bk-t-date{font-family:var(--mono);font-size:12px;color:var(--yolo);margin-bottom:4px;}
  .bk-t-title{font-size:18px;font-weight:700;margin-bottom:4px;}
  .bk-t-school{color:var(--muted);font-size:14px;}

  .bk-contact-grid{display:grid;grid-template-columns:1.1fr 1fr;gap:60px;align-items:start;}
  .bk-contact-cards{display:flex;flex-direction:column;gap:14px;}
  .bk-c-card{display:flex;align-items:center;gap:16px;border:1px solid var(--line);background:var(--surface);padding:18px 20px;border-radius:8px;transition:border-color .2s, transform .2s;}
  .bk-c-card:hover{border-color:var(--teal);transform:translateX(6px);}
  .bk-c-icon{width:38px;height:38px;border-radius:8px;background:var(--surface-2);display:flex;align-items:center;justify-content:center;flex-shrink:0;color:var(--yolo);}
  .bk-c-label{font-family:var(--mono);font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.05em;}
  .bk-c-value{font-size:14.5px;color:var(--text);word-break:break-word;}
  .bk-avail-box{border:1px solid rgba(232,164,0,.35);background:var(--yolo-soft);border-radius:8px;padding:26px;}
  .bk-avail-box h3{font-size:17px;margin-bottom:10px;}
  .bk-avail-box p{color:#5B4600;font-size:14px;margin-bottom:6px;}
  .bk-avail-box p strong{color:#231A00;font-weight:600;}


  .bk-footer{border-top:1px solid var(--line);padding:36px 0;position:relative;z-index:1;}

  .bk-scrolltop{
    position:fixed;bottom:24px;right:24px;z-index:300;width:46px;height:46px;border-radius:50%;
    background:var(--yolo);color:#12151F;border:none;font-size:20px;font-weight:700;cursor:pointer;
    box-shadow:0 10px 24px rgba(232,164,0,.35);
    opacity:0;transform:translateY(12px) scale(.9);pointer-events:none;
    transition:opacity .25s, transform .25s, background .2s;
  }
  .bk-scrolltop.visible{opacity:1;transform:translateY(0) scale(1);pointer-events:auto;}
  .bk-scrolltop:hover{background:#ffb814;}
  @media (max-width:640px){.bk-scrolltop{bottom:18px;right:18px;width:42px;height:42px;}}
  .bk-foot-row{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px;font-family:var(--mono);font-size:12px;color:var(--muted);}

  @media (max-width:800px){
    .bk-navlinks{display:none;}
    .bk-burger{display:flex;}
    .bk-contact-grid{grid-template-columns:1fr;}
    .bk-section{padding:64px 0;}
    .bk-proj-note{margin-top:-24px;}
    .bk-nav{padding:14px 20px;}
    .bk-wrap{padding:0 20px;}
    .bk-exp-card{padding:24px 20px;}
    .bk-avail-box{padding:20px;}
  }
  @media (max-width:640px){
    .bk-hero{padding:50px 0 40px;}
    .bk-stats-strip{gap:20px;}
    .bk-stat{min-width:calc(50% - 10px);flex:0 0 calc(50% - 10px);}
    .bk-hero-meta{gap:14px;font-size:12px;}
    .bk-cta-row{gap:10px;}
    .bk-btn{padding:12px 18px;font-size:12px;}
    .bk-why-cycle-item h4{font-size:19px;}
    .bk-t-item{padding-left:32px;}
    .bk-timeline::before{left:6px;}
    .bk-proj-body{padding:22px 20px 24px;}
    .bk-marquee-track{gap:24px;font-size:12px;}
  }
  @media (max-width:420px){
    .bk-wrap{padding:0 16px;}
    .bk-logo{font-size:13px;}
    .bk-stat{min-width:100%;flex:0 0 100%;}
  }
  .bk-robot-wrap{
    position:fixed;bottom:clamp(10px,4vw,18px);left:0;z-index:200;pointer-events:none;
    display:flex;flex-direction:column;align-items:center;
    animation:bk-robot-walk 11s cubic-bezier(.45,0,.55,1) forwards;
  }
  @keyframes bk-robot-walk{
    0%{transform:translateX(-140px);}
    28%{transform:translateX(40vw);}
    72%{transform:translateX(40vw);}
    100%{transform:translateX(calc(100vw + 60px));}
  }
  .bk-robot-bounce{
    width:clamp(40px,11vw,64px);height:auto;
    animation:bk-robot-bounce .5s ease-in-out infinite alternate;
  }
  @keyframes bk-robot-bounce{from{transform:translateY(0) rotate(-1.5deg);}to{transform:translateY(-6px) rotate(1.5deg);}}
  .bk-robot-leg{animation:bk-robot-leg .4s ease-in-out infinite alternate;transform-origin:top center;}
  .bk-robot-leg.right{animation-delay:.2s;}
  @keyframes bk-robot-leg{from{transform:rotate(-18deg);}to{transform:rotate(18deg);}}
  .bk-robot-led{animation:bk-pulseDot 1s ease-in-out infinite;}
  .bk-robot-bubble{
    background:var(--surface);border:1px solid var(--line-strong);border-radius:12px;
    padding:clamp(5px,1.6vw,8px) clamp(8px,3vw,14px);margin-bottom:6px;
    font-family:var(--mono);font-size:clamp(9.5px,2.6vw,12px);color:var(--text);
    width:max-content;max-width:min(78vw,320px);white-space:normal;text-align:center;line-height:1.35;
    overflow-wrap:break-word;word-break:break-word;
    box-shadow:0 8px 20px rgba(16,24,40,.14);
    animation:bk-bubble-pop .4s cubic-bezier(.34,1.56,.64,1) both;
    position:relative;
  }
  .bk-robot-bubble::after{
    content:'';position:absolute;left:50%;bottom:-6px;transform:translateX(-50%);
    width:12px;height:12px;background:var(--surface);border-right:1px solid var(--line-strong);
    border-bottom:1px solid var(--line-strong);rotate:45deg;
  }
  @keyframes bk-bubble-pop{from{opacity:0;transform:scale(.6) translateY(6px);}to{opacity:1;transform:scale(1) translateY(0);}}
  @media (prefers-reduced-motion:reduce){.bk-robot-wrap{display:none;}}
  @media (prefers-reduced-motion:reduce){ .bk-root *{animation:none !important;transition:none !important;} }
`;

