function EmailCard({ email }) {
  const [copied, setCopied] = useState(false);

  const handleCopy = async (e) => {
    e.preventDefault();
    try {
      if (navigator.clipboard && navigator.clipboard.writeText) {
        await navigator.clipboard.writeText(email);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
      } else {
        window.location.href = "mailto:" + email;
      }
    } catch {
      window.location.href = "mailto:" + email;
    }
  };

  return (
    <div className="bk-c-card">
      <div className="bk-c-icon">✉</div>
      <div style={{ flex: 1 }}>
        <div className="bk-c-label">Email</div>
        <div className="bk-c-value">{email}</div>
      </div>
      <button className={"bk-copy-btn" + (copied ? " copied" : "")} onClick={handleCopy} type="button">
        {copied ? "✓ Copié" : "Copier"}
      </button>
    </div>
  );
}

function TerminalCard() {
  const [progress, setProgress] = useState({ lineIndex: 0, charIndex: 0 });

  useEffect(() => {
    let cancelled = false;
    let li = 0;
    let ci = 0;
    const TYPE_SPEED = 16;
    const LINE_PAUSE = 90;
    const LOOP_PAUSE = 2800;

    const step = () => {
      if (cancelled) return;
      if (li >= TERMINAL_LINES.length) {
        setTimeout(() => {
          if (cancelled) return;
          li = 0;
          ci = 0;
          setProgress({ lineIndex: li, charIndex: ci });
          setTimeout(step, TYPE_SPEED);
        }, LOOP_PAUSE);
        return;
      }
      const lineLen = TERMINAL_LINES[li].plain.length;
      if (ci >= lineLen) {
        li++;
        ci = 0;
        setProgress({ lineIndex: li, charIndex: ci });
        setTimeout(step, LINE_PAUSE);
        return;
      }
      ci++;
      setProgress({ lineIndex: li, charIndex: ci });
      setTimeout(step, TYPE_SPEED);
    };

    const kickoff = setTimeout(step, 500);
    return () => {
      cancelled = true;
      clearTimeout(kickoff);
    };
  }, []);

  return (
    <div className="bk-terminal-card">
      <div className="bk-terminal-bar">
        <span className="bk-terminal-dot" style={{ background: "#FF5F57" }} />
        <span className="bk-terminal-dot" style={{ background: "#FEBC2E" }} />
        <span className="bk-terminal-dot" style={{ background: "#28C840" }} />
        <span className="bk-terminal-filename">kaizen_detect.py</span>
      </div>
      <div className="bk-terminal-body">
        {TERMINAL_LINES.map((line, i) => {
          if (i < progress.lineIndex) return <div key={i}>{line.node}</div>;
          if (i === progress.lineIndex)
            return (
              <div key={i}>
                {line.plain.slice(0, progress.charIndex)}
                <span className="bk-terminal-cursor" />
              </div>
            );
          return <div key={i}>{"\u00A0"}</div>;
        })}
        {progress.lineIndex >= TERMINAL_LINES.length && (
          <div>
            <span className="bk-terminal-cursor" />
          </div>
        )}
      </div>
    </div>
  );
}

