function Lightbox({ images, index, onClose, onPrev, onNext, onDot }) {
  useEffect(() => {
    const onKey = (e) => {
      if (e.key === "Escape") onClose();
      if (e.key === "ArrowLeft") onPrev();
      if (e.key === "ArrowRight") onNext();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose, onPrev, onNext]);

  return (
    <div className="bk-lightbox-backdrop" onClick={onClose}>
      <div className="bk-lightbox-inner" onClick={(e) => e.stopPropagation()}>
        <button className="bk-lightbox-close" onClick={onClose} aria-label="Fermer">✕</button>
        {images.length > 1 && (
          <button className="bk-lightbox-nav prev" onClick={onPrev} aria-label="Image précédente">‹</button>
        )}
        <img src={images[index]} alt={`Aperçu ${index + 1} sur ${images.length}`} />
        {images.length > 1 && (
          <button className="bk-lightbox-nav next" onClick={onNext} aria-label="Image suivante">›</button>
        )}
        <div className="bk-lightbox-caption">{index + 1} / {images.length}</div>
        {images.length > 1 && (
          <div className="bk-lightbox-dots">
            {images.map((_, i) => (
              <span key={i} className={i === index ? "active" : ""} onClick={() => onDot(i)} />
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

function Reveal({ children, className = "", id }) {
  const ref = useRef(null);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const obs = new IntersectionObserver(
      (entries) => {
        entries.forEach((e) => {
          if (e.isIntersecting) {
            el.classList.add("in");
            const kids = el.querySelectorAll(".bk-exp-card, .bk-proj-card, .bk-t-item, .bk-c-card");
            kids.forEach((k, i) => {
              k.style.animationDelay = i * 0.08 + "s";
            });
          }
        });
      },
      { threshold: 0.12 }
    );
    obs.observe(el);
    return () => obs.disconnect();
  }, []);
  return (
    <section id={id} className="bk-section">
      <div ref={ref} className={`bk-wrap bk-reveal bk-stagger ${className}`}>
        {children}
      </div>
    </section>
  );
}

function Stat({ count, label }) {
  const ref = useRef(null);
  const [value, setValue] = useState(0);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const obs = new IntersectionObserver(
      (entries) => {
        entries.forEach((e) => {
          if (e.isIntersecting) {
            let current = 0;
            const step = Math.max(1, Math.round(count / 30));
            const iv = setInterval(() => {
              current += step;
              if (current >= count) {
                current = count;
                clearInterval(iv);
              }
              setValue(current);
            }, 40);
            obs.unobserve(el);
          }
        });
      },
      { threshold: 0.5 }
    );
    obs.observe(el);
    return () => obs.disconnect();
  }, [count]);
  return (
    <div className="bk-stat" ref={ref}>
      <div className="bk-stat-num">{value}</div>
      <div className="bk-stat-label">{label}</div>
    </div>
  );
}

